// ============ 有向图和无向图的存储差别 ============
//
// 只有一个：**有向图只填一个格子**。
//
//   g[i][j] = 1  表示有一条从 i 指向 j 的边
//
// 无向图要填 g[i][j] 和 g[j][i] 两个，有向图只填一个 —— 因为方向是有意义的。
//
// 所以这个矩阵**不对称**。如果打印出来发现对称了，那说明建图时写成了无向图。
//
// ============ 入度是什么 ============
//
// 顶点 v 的**入度** = 有多少条边指向 v = **有多少个任务必须在 v 之前完成**。
//
//   · 入度 = 0  →  没有前置任务，现在就能做
//   · 入度 > 0  →  还有前置任务没做完
//
// 所以拓扑排序从头到尾都在盯着这个数。
//
// ============ 出度 ============
//
// 顺便说一下**出度**：有多少条边从 v 指出去。
//
//   入度 = "我要等谁"
//   出度 = "谁要等我"
//
// 拓扑排序主要用入度，出度在做关键路径（AOE 网）时才用得上。

// 最多顶点数
#define MAXV 100

// 有向图（邻接矩阵）
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// g[i][j] = 1 表示有一条 i → j 的边
    int g[MAXV][MAXV];
} DGraph;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 用边表建有向图
// edges 每条边 { 起点, 终点 }
void CreateDGraph(DGraph *G, int nv, const int edges[][2], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 清零
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = 0;
        }
    }

// 逐条边（只填一个格子！）
// 这就是有向图和无向图在存储上的唯一区别。
    for (i = 0; i < edgeCount; i++)
    {
        G->g[edges[i][0]][edges[i][1]] = 1;
    }
}

// 计算每个顶点的入度
// 入度 = 第 j 列上有多少个 1。
void CalcIndegree(DGraph *G, int indegree[])
{
// 循环用
    int i, j;

// 先清零
    for (i = 0; i < G->nv; i++)
    {
        indegree[i] = 0;
    }

// 逐列累加
    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
// 有一条 i→j 的边，j 的入度就加一
            if (G->g[i][j] != 0)
            {
                indegree[j]++;
            }
        }
    }
}

// 计算出度（拓扑排序用不上，但对比着看更清楚）
int OutDegree(DGraph *G, int v)
{
// 第 v 行上有多少个 1
    int i;
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0)
        {
            count++;
        }
    }
    return count;
}

