// ============ 走一遍 ============
//
// 用这张课表：
//
//      0 ──→ 2 ──→ 4
//      ↓           ↑
//      1 ──→ 3 ────┘
//
//   边：(0,2) (0,1) (1,3) (2,4) (3,4)
//
// 各点入度：0 号 0、1 号 1、2 号 1、3 号 1、4 号 2
//
//   初始队列：只有 0（唯一的入度 0）
//
//   **第 1 步**：输出 0，删掉 0 的出边
//        邻居是按**下标从小到大**扫的（for i = 0..nv-1），所以先碰到 1：
//        到 1 的边没了 → 1 的入度 1→0，入队
//        再到 2 的边没了 → 2 的入度 1→0，入队
//        队列 [1, 2]，已输出 0
//
//   **第 2 步**：输出 1（队列先进先出，1 比 2 先进），删掉 1 的出边
//        到 3 的边没了 → 3 的入度 1→0，入队
//        队列 [2, 3]，已输出 0 1
//
//   **第 3 步**：输出 2，删掉 2 的出边
//        到 4 的边没了 → 4 的入度 2→1（还不是 0）
//        队列 [3]，已输出 0 1 2
//
//   **第 4 步**：输出 3，删掉 3 的出边
//        到 4 的边没了 → 4 入度 1→0，入队
//        队列 [4]，已输出 0 1 2 3
//
//   **第 5 步**：输出 4，它没有出边
//        队列空，结束
//
// 结果：**0 1 2 3 4**
//
// 注意这里的关键：第 1 步里 1 和 2 是**同时**变成入度 0 的，
// 谁先输出都合法。本实现按邻居下标从小到大扫，所以 1 先进队、先输出。
// 换成 DFS 逆后序（本文件后面那个算法）会得到 0 2 1 3 4 —— 两个都对，
// 拓扑序本来就不唯一。
//
// ============ 为什么"删掉出边"就是入度减一 ============
//
// 因为入度的定义就是"有多少条边指向我"。
// 把某条指向我的边删掉，我的入度当然就少一。
//
// 代码里不用真的去改矩阵，只要把邻居的 indegree 减一就行 ——
// 这正是"用一个计数器代替真的删边"的常见技巧。
//
// ============ 注意拓扑排序不唯一 ============
//
// 如果某一时刻队列里有多个入度 0 的顶点，先输出谁都可以，
// 结果都是合法的。
//
// 所以做题时题目通常会规定"编号小的优先输出"，来固定答案。
// 我们这个实现用的是队列（先进先出），结果和入队顺序有关。

// 拓扑排序，结果放进 order 数组；返回排好的顶点数
// 返回值 < nv 表示图里有环，拓扑序不存在
int TopSort(DGraph *G, int order[])
{
// 入度数组（会一边用一边减）
    int indegree[MAXV];
// 队列：就地开数组
    int queue[MAXV];
// 队头、队尾
    int front = 0;
    int rear = 0;
// 已经输出了几个
    int count = 0;
// 循环用
    int i;
// 当前顶点
    int v;

// ① 先算好入度
    CalcIndegree(G, indegree);

// ② 入度为 0 的全部入队
// 它们是"没有前置任务"的那些，随时可以做。
    for (i = 0; i < G->nv; i++)
    {
        if (indegree[i] == 0)
        {
            queue[rear++] = i;
        }
    }

// ③ 队列不空就一直转
    while (front < rear)
    {
// 取出一个顶点
        v = queue[front++];

// 输出它
        order[count++] = v;

// ④ 删掉它的所有出边 —— 也就是让邻居的入度减一
        for (i = 0; i < G->nv; i++)
        {
            if (G->g[v][i] != 0)
            {
// 入度减一
// 先减再判断，写成 --indegree[i] == 0 就是"减完正好是 0"。
                if (--indegree[i] == 0)
                {
// 变成 0 就说明它的前置任务都做完了，可以入队
                    queue[rear++] = i;
                }
            }
        }
    }

// ④ 检查是不是所有顶点都输出了
// 输出数少于顶点数，说明剩下的顶点入度都降不到 0 —— 它们在环上。
    return count;
}

// 判断图里有没有环
// 判据就是"拓扑排序能不能排完所有顶点"。
int HasCycle(DGraph *G)
{
// 拓扑序
    int order[MAXV];
// 排出来的个数
    int n;

    n = TopSort(G, order);

// 排不满就是有环
    return n != G->nv;
}

