// 这个函数是给下一个模块（DFS 版拓扑排序）用的。
//
// 它做的事就是普通的深度优先，唯一的特别之处在**最后一行**：
// 访问完所有邻居之后，把顶点填到 order 数组的**尾部往前**的位置上。

void DFSVisit(DGraph *G, int v, int visited[], int order[], int *pos)
{
// 循环用
    int i;

// 标记已访问
    visited[v] = 1;

// 先递归所有邻居
    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0 && visited[i] == 0)
        {
            DFSVisit(G, i, visited, order, pos);
        }
    }

// 邻居都处理完了，才把自己填进去
// 差别就在这一句的位置 —— 放在循环**之后**就是"后序"，
// 而逆后序正好就是拓扑序。
    order[(*pos)--] = v;
}

modes.short:
void DFSVisit(DGraph *G, int v, int visited[], int order[], int *pos)
{
// 循环用
    int i;

// 标记已访问
    visited[v] = 1;

// 先递归所有邻居
    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0 && visited[i] == 0)
