// ============ 为什么"逆后序"就是拓扑序 ============
//
// 先想清楚后序是什么：**在树/图的 DFS 里，一个顶点的"后序位置"
// 是它的所有邻居都处理完之后才确定的。**
//
// 所以如果有一条边 A → B，那么：
//
//   · 从 A 出发会先递归到 B
//   · B 会**先于 A** 拿到后序位置
//   · 也就是说：**A 的后序位置 > B 的后序位置**（A 更靠后）
//
// 那我把后序位置**反过来用**（谁后序靠后就放前面），得到的就是：
//
//   · A 排在 B 前面
//
// 正好符合"A 必须在 B 之前"！
//
// 所以在代码里，从数组**最后往前**填就行了。
//
// ============ 和 Kahn 算法的对比 ============
//
//   Kahn（入度法）：思路直观，顺序好控制，还能顺手检测环
//   DFS 逆后序：   代码更短，不用算入度，但顺序不好控制
//
// 两者都能用。考试里 Kahn 更常见，因为它"看得见过程"。
//
// 注意：DFS 版**不能直接用来检测环**，它照样能输出一个序列 ——
// 只是有环时那个序列没有意义。要检测环得另外做标记（三种颜色）。

// 用 DFS 逆后序做拓扑排序
// 返回排好的顶点数（这里总是 nv，不检测环）
int TopSortDFS(DGraph *G, int order[])
{
// 访问标记
    int visited[MAXV];
// 填充位置（从最后一个位置开始往前）
    int pos;
// 循环用
    int i;

// 都还没访问
    for (i = 0; i < G->nv; i++)
    {
        visited[i] = 0;
    }

// 从末尾往前填
    pos = G->nv - 1;

// 每个没访问过的顶点都起一次 DFS
// 外层这个循环是为了处理"非连通"的有向图。
    for (i = 0; i < G->nv; i++)
    {
        if (visited[i] == 0)
        {
            DFSVisit(G, i, visited, order, &pos);
        }
    }

// 全部填满
    return G->nv;
}

// 打印一个序列
void PrintOrder(const char *tag, int order[], int n)
{
// 循环用
    int i;

    printf("%s", tag);
    for (i = 0; i < n; i++)
    {
        printf("%d ", order[i]);
    }
    printf("\n");
}

