/* ======== [已给出] 模块 02 TopSort ======== */

int TopSort(DGraph *G, int order[])
{
    int indegree[MAXV];
    int queue[MAXV];
    int front = 0;
    int rear = 0;
    int count = 0;
    int i;
    int v;

    CalcIndegree(G, indegree);

    for (i = 0; i < G->nv; i++)
    {
        if (indegree[i] == 0)
        {
            queue[rear++] = i;
        }
    }

    while (front < rear)
    {
        v = queue[front++];

        order[count++] = v;

        for (i = 0; i < G->nv; i++)
        {
            if (G->g[v][i] != 0)
            {
                if (--indegree[i] == 0)
                {
                    queue[rear++] = i;
                }
            }
        }
    }

    return count;
}

int HasCycle(DGraph *G)
{
    int order[MAXV];
    int n;

    n = TopSort(G, order);

    return n != G->nv;
}

/* ======== [已给出] 模块 03 DFSVisit ======== */

void DFSVisit(DGraph *G, int v, int visited[], int order[], int *pos)
{
    int i;

    visited[v] = 1;

    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0 && visited[i] == 0)
        {
            DFSVisit(G, i, visited, order, pos);
        }
    }

    order[(*pos)--] = v;
}

