#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

#define MAXV 100

typedef struct
{
    int nv;
    int ne;
    int g[MAXV][MAXV];
} DGraph;

#define OK 1
#define ERROR 0
typedef int Status;

void CreateDGraph(DGraph *G, int nv, const int edges[][2], int edgeCount)
{
    int i, j;

    G->nv = nv;
    G->ne = edgeCount;

    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = 0;
        }
    }

    for (i = 0; i < edgeCount; i++)
    {
        G->g[edges[i][0]][edges[i][1]] = 1;
    }
}

void CalcIndegree(DGraph *G, int indegree[])
{
    int i, j;

    for (i = 0; i < G->nv; i++)
    {
        indegree[i] = 0;
    }

    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
            if (G->g[i][j] != 0)
            {
                indegree[j]++;
            }
        }
    }
}

int OutDegree(DGraph *G, int v)
{
    int i;
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0)
        {
            count++;
        }
    }
    return count;
}

/* ======== [已给出] 模块 02 TopSort ======== */

int TopSort(DGraph *G, int order[])
{
    int indegree[MAXV];
    int queue[MAXV];
    int front = 0;
    int rear = 0;
    int count = 0;
    int i;
    int v;

    CalcIndegree(G, indegree);

    for (i = 0; i < G->nv; i++)
    {
        if (indegree[i] == 0)
        {
            queue[rear++] = i;
        }
    }

    while (front < rear)
    {
        v = queue[front++];

        order[count++] = v;

        for (i = 0; i < G->nv; i++)
        {
            if (G->g[v][i] != 0)
            {
                if (--indegree[i] == 0)
                {
                    queue[rear++] = i;
                }
            }
        }
    }

    return count;
}

int HasCycle(DGraph *G)
{
    int order[MAXV];
    int n;

    n = TopSort(G, order);

    return n != G->nv;
}

/* ======== [已给出] 模块 03 DFSVisit ======== */

void DFSVisit(DGraph *G, int v, int visited[], int order[], int *pos)
{
    int i;

    visited[v] = 1;

    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0 && visited[i] == 0)
        {
            DFSVisit(G, i, visited, order, pos);
        }
    }

    order[(*pos)--] = v;
}

/* ======== [已给出] 模块 04 TopSortDFS ======== */

int TopSortDFS(DGraph *G, int order[])
{
    int visited[MAXV];
    int pos;
    int i;

    for (i = 0; i < G->nv; i++)
    {
        visited[i] = 0;
    }

    pos = G->nv - 1;

    for (i = 0; i < G->nv; i++)
    {
        if (visited[i] == 0)
        {
            DFSVisit(G, i, visited, order, &pos);
        }
    }

    return G->nv;
}

