#include <stdio.h>
#include <stdlib.h>

// ============ 有向图和无向图的存储差别 ============
//
// 只有一个：**有向图只填一个格子**。
//
//   g[i][j] = 1  表示有一条从 i 指向 j 的边
//
// 无向图要填 g[i][j] 和 g[j][i] 两个，有向图只填一个 —— 因为方向是有意义的。
//
// 所以这个矩阵**不对称**。如果打印出来发现对称了，那说明建图时写成了无向图。
//
// ============ 入度是什么 ============
//
// 顶点 v 的**入度** = 有多少条边指向 v = **有多少个任务必须在 v 之前完成**。
//
//   · 入度 = 0  →  没有前置任务，现在就能做
//   · 入度 > 0  →  还有前置任务没做完
//
// 所以拓扑排序从头到尾都在盯着这个数。
//
// ============ 出度 ============
//
// 顺便说一下**出度**：有多少条边从 v 指出去。
//
//   入度 = "我要等谁"
//   出度 = "谁要等我"
//
// 拓扑排序主要用入度，出度在做关键路径（AOE 网）时才用得上。

// 最多顶点数
#define MAXV 100

// 有向图（邻接矩阵）
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// g[i][j] = 1 表示有一条 i → j 的边
    int g[MAXV][MAXV];
} DGraph;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 用边表建有向图
// edges 每条边 { 起点, 终点 }
void CreateDGraph(DGraph *G, int nv, const int edges[][2], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 清零
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = 0;
        }
    }

// 逐条边（只填一个格子！）
// 这就是有向图和无向图在存储上的唯一区别。
    for (i = 0; i < edgeCount; i++)
    {
        G->g[edges[i][0]][edges[i][1]] = 1;
    }
}

// 计算每个顶点的入度
// 入度 = 第 j 列上有多少个 1。
void CalcIndegree(DGraph *G, int indegree[])
{
// 循环用
    int i, j;

// 先清零
    for (i = 0; i < G->nv; i++)
    {
        indegree[i] = 0;
    }

// 逐列累加
    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
// 有一条 i→j 的边，j 的入度就加一
            if (G->g[i][j] != 0)
            {
                indegree[j]++;
            }
        }
    }
}

// 计算出度（拓扑排序用不上，但对比着看更清楚）
int OutDegree(DGraph *G, int v)
{
// 第 v 行上有多少个 1
    int i;
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0)
        {
            count++;
        }
    }
    return count;
}

// ============ 走一遍 ============
//
// 用这张课表：
//
//      0 ──→ 2 ──→ 4
//      ↓           ↑
//      1 ──→ 3 ────┘
//
//   边：(0,2) (0,1) (1,3) (2,4) (3,4)
//
// 各点入度：0 号 0、1 号 1、2 号 1、3 号 1、4 号 2
//
//   初始队列：只有 0（唯一的入度 0）
//
//   **第 1 步**：输出 0，删掉 0 的出边
//        邻居是按**下标从小到大**扫的（for i = 0..nv-1），所以先碰到 1：
//        到 1 的边没了 → 1 的入度 1→0，入队
//        再到 2 的边没了 → 2 的入度 1→0，入队
//        队列 [1, 2]，已输出 0
//
//   **第 2 步**：输出 1（队列先进先出，1 比 2 先进），删掉 1 的出边
//        到 3 的边没了 → 3 的入度 1→0，入队
//        队列 [2, 3]，已输出 0 1
//
//   **第 3 步**：输出 2，删掉 2 的出边
//        到 4 的边没了 → 4 的入度 2→1（还不是 0）
//        队列 [3]，已输出 0 1 2
//
//   **第 4 步**：输出 3，删掉 3 的出边
//        到 4 的边没了 → 4 入度 1→0，入队
//        队列 [4]，已输出 0 1 2 3
//
//   **第 5 步**：输出 4，它没有出边
//        队列空，结束
//
// 结果：**0 1 2 3 4**
//
// 注意这里的关键：第 1 步里 1 和 2 是**同时**变成入度 0 的，
// 谁先输出都合法。本实现按邻居下标从小到大扫，所以 1 先进队、先输出。
// 换成 DFS 逆后序（本文件后面那个算法）会得到 0 2 1 3 4 —— 两个都对，
// 拓扑序本来就不唯一。
//
// ============ 为什么"删掉出边"就是入度减一 ============
//
// 因为入度的定义就是"有多少条边指向我"。
// 把某条指向我的边删掉，我的入度当然就少一。
//
// 代码里不用真的去改矩阵，只要把邻居的 indegree 减一就行 ——
// 这正是"用一个计数器代替真的删边"的常见技巧。
//
// ============ 注意拓扑排序不唯一 ============
//
// 如果某一时刻队列里有多个入度 0 的顶点，先输出谁都可以，
// 结果都是合法的。
//
// 所以做题时题目通常会规定"编号小的优先输出"，来固定答案。
// 我们这个实现用的是队列（先进先出），结果和入队顺序有关。

// 拓扑排序，结果放进 order 数组；返回排好的顶点数
// 返回值 < nv 表示图里有环，拓扑序不存在
int TopSort(DGraph *G, int order[])
{
// 入度数组（会一边用一边减）
    int indegree[MAXV];
// 队列：就地开数组
    int queue[MAXV];
// 队头、队尾
    int front = 0;
    int rear = 0;
// 已经输出了几个
    int count = 0;
// 循环用
    int i;
// 当前顶点
    int v;

// ① 先算好入度
    CalcIndegree(G, indegree);

// ② 入度为 0 的全部入队
// 它们是"没有前置任务"的那些，随时可以做。
    for (i = 0; i < G->nv; i++)
    {
        if (indegree[i] == 0)
        {
            queue[rear++] = i;
        }
    }

// ③ 队列不空就一直转
    while (front < rear)
    {
// 取出一个顶点
        v = queue[front++];

// 输出它
        order[count++] = v;

// ④ 删掉它的所有出边 —— 也就是让邻居的入度减一
        for (i = 0; i < G->nv; i++)
        {
            if (G->g[v][i] != 0)
            {
// 入度减一
// 先减再判断，写成 --indegree[i] == 0 就是"减完正好是 0"。
                if (--indegree[i] == 0)
                {
// 变成 0 就说明它的前置任务都做完了，可以入队
                    queue[rear++] = i;
                }
            }
        }
    }

// ④ 检查是不是所有顶点都输出了
// 输出数少于顶点数，说明剩下的顶点入度都降不到 0 —— 它们在环上。
    return count;
}

// 判断图里有没有环
// 判据就是"拓扑排序能不能排完所有顶点"。
int HasCycle(DGraph *G)
{
// 拓扑序
    int order[MAXV];
// 排出来的个数
    int n;

    n = TopSort(G, order);

// 排不满就是有环
    return n != G->nv;
}

// 这个函数是给下一个模块（DFS 版拓扑排序）用的。
//
// 它做的事就是普通的深度优先，唯一的特别之处在**最后一行**：
// 访问完所有邻居之后，把顶点填到 order 数组的**尾部往前**的位置上。

void DFSVisit(DGraph *G, int v, int visited[], int order[], int *pos)
{
// 循环用
    int i;

// 标记已访问
    visited[v] = 1;

// 先递归所有邻居
    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0 && visited[i] == 0)
        {
            DFSVisit(G, i, visited, order, pos);
        }
    }

// 邻居都处理完了，才把自己填进去
// 差别就在这一句的位置 —— 放在循环**之后**就是"后序"，
// 而逆后序正好就是拓扑序。
    order[(*pos)--] = v;
}

// ============ 为什么"逆后序"就是拓扑序 ============
//
// 先想清楚后序是什么：**在树/图的 DFS 里，一个顶点的"后序位置"
// 是它的所有邻居都处理完之后才确定的。**
//
// 所以如果有一条边 A → B，那么：
//
//   · 从 A 出发会先递归到 B
//   · B 会**先于 A** 拿到后序位置
//   · 也就是说：**A 的后序位置 > B 的后序位置**（A 更靠后）
//
// 那我把后序位置**反过来用**（谁后序靠后就放前面），得到的就是：
//
//   · A 排在 B 前面
//
// 正好符合"A 必须在 B 之前"！
//
// 所以在代码里，从数组**最后往前**填就行了。
//
// ============ 和 Kahn 算法的对比 ============
//
//   Kahn（入度法）：思路直观，顺序好控制，还能顺手检测环
//   DFS 逆后序：   代码更短，不用算入度，但顺序不好控制
//
// 两者都能用。考试里 Kahn 更常见，因为它"看得见过程"。
//
// 注意：DFS 版**不能直接用来检测环**，它照样能输出一个序列 ——
// 只是有环时那个序列没有意义。要检测环得另外做标记（三种颜色）。

// 用 DFS 逆后序做拓扑排序
// 返回排好的顶点数（这里总是 nv，不检测环）
int TopSortDFS(DGraph *G, int order[])
{
// 访问标记
    int visited[MAXV];
// 填充位置（从最后一个位置开始往前）
    int pos;
// 循环用
    int i;

// 都还没访问
    for (i = 0; i < G->nv; i++)
    {
        visited[i] = 0;
    }

// 从末尾往前填
    pos = G->nv - 1;

// 每个没访问过的顶点都起一次 DFS
// 外层这个循环是为了处理"非连通"的有向图。
    for (i = 0; i < G->nv; i++)
    {
        if (visited[i] == 0)
        {
            DFSVisit(G, i, visited, order, &pos);
        }
    }

// 全部填满
    return G->nv;
}

// 打印一个序列
void PrintOrder(const char *tag, int order[], int n)
{
// 循环用
    int i;

    printf("%s", tag);
    for (i = 0; i < n; i++)
    {
        printf("%d ", order[i]);
    }
    printf("\n");
}

// ============ 序列不一样，但都对 ============
//
// 拓扑排序不唯一。只要每条边都"从前往后"，就是合法答案。
//
// 所以两个算法给出不同的序列是**正常现象**，不用去对答案。
// 真正该检查的是：**结果里每条边的方向对不对**。
//
// 验证办法：记下每个顶点在结果里的位置，然后遍历所有边，
// 检查是不是"起点的位置 < 终点的位置"。

// 检查一个序列是不是合法拓扑序
// 返回 1 表示合法
int CheckOrder(DGraph *G, int order[])
{
// 每个顶点在序列里的位置
    int pos[MAXV];
// 循环用
    int i, j;

// 先记下位置
    for (i = 0; i < G->nv; i++)
    {
        pos[order[i]] = i;
    }

// 检查每条边
    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
// 有边 i→j，那 i 必须排在 j 前面
            if (G->g[i][j] != 0 && pos[i] >= pos[j])
            {
                printf("  违反：边 %d→%d，但 %d 排在 %d 后面\n", i, j, i, j);
                return 0;
            }
        }
    }
    return 1;
}

// 主函数
