#include <stdio.h>
#include <stdlib.h>


// 最多顶点数
#define MAXV 100

// 有向图（邻接矩阵）
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// g[i][j] = 1 表示有一条 i → j 的边
    int g[MAXV][MAXV];
} DGraph;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 用边表建有向图
void CreateDGraph(DGraph *G, int nv, const int edges[][2], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 清零
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = 0;
        }
    }

// 逐条边（只填一个格子！）
    for (i = 0; i < edgeCount; i++)
    {
        G->g[edges[i][0]][edges[i][1]] = 1;
    }
}

// 计算每个顶点的入度
void CalcIndegree(DGraph *G, int indegree[])
{
// 循环用
    int i, j;

// 先清零
    for (i = 0; i < G->nv; i++)
    {
        indegree[i] = 0;
    }

// 逐列累加
    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
// 有一条 i→j 的边，j 的入度就加一
            if (G->g[i][j] != 0)
            {
                indegree[j]++;
            }
        }
    }
}

// 计算出度（拓扑排序用不上，但对比着看更清楚）
int OutDegree(DGraph *G, int v)
{
// 第 v 行上有多少个 1
    int i;
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0)
        {
            count++;
        }
    }
    return count;
}


// 拓扑排序，结果放进 order 数组；返回排好的顶点数
int TopSort(DGraph *G, int order[])
{
// 入度数组（会一边用一边减）
    int indegree[MAXV];
// 队列：就地开数组
    int queue[MAXV];
// 队头、队尾
    int front = 0;
    int rear = 0;
// 已经输出了几个
    int count = 0;
// 循环用
    int i;
// 当前顶点
    int v;

// ① 先算好入度
    CalcIndegree(G, indegree);

// ② 入度为 0 的全部入队
    for (i = 0; i < G->nv; i++)
    {
        if (indegree[i] == 0)
        {
            queue[rear++] = i;
        }
    }

// ③ 队列不空就一直转
    while (front < rear)
    {
// 取出一个顶点
        v = queue[front++];

// 输出它
        order[count++] = v;

// ④ 删掉它的所有出边 —— 也就是让邻居的入度减一
        for (i = 0; i < G->nv; i++)
        {
            if (G->g[v][i] != 0)
            {
// 入度减一
                if (--indegree[i] == 0)
                {
// 变成 0 就说明它的前置任务都做完了，可以入队
                    queue[rear++] = i;
                }
            }
        }
    }

// ④ 检查是不是所有顶点都输出了
    return count;
}

// 判断图里有没有环
int HasCycle(DGraph *G)
{
// 拓扑序
    int order[MAXV];
// 排出来的个数
    int n;

    n = TopSort(G, order);

// 排不满就是有环
    return n != G->nv;
}


void DFSVisit(DGraph *G, int v, int visited[], int order[], int *pos)
{
// 循环用
    int i;

// 标记已访问
    visited[v] = 1;

// 先递归所有邻居
    for (i = 0; i < G->nv; i++)
    {
        if (G->g[v][i] != 0 && visited[i] == 0)
        {
            DFSVisit(G, i, visited, order, pos);
        }
    }

// 邻居都处理完了，才把自己填进去
    order[(*pos)--] = v;
}


// 用 DFS 逆后序做拓扑排序
int TopSortDFS(DGraph *G, int order[])
{
// 访问标记
    int visited[MAXV];
// 填充位置（从最后一个位置开始往前）
    int pos;
// 循环用
    int i;

// 都还没访问
    for (i = 0; i < G->nv; i++)
    {
        visited[i] = 0;
    }

// 从末尾往前填
    pos = G->nv - 1;

// 每个没访问过的顶点都起一次 DFS
    for (i = 0; i < G->nv; i++)
    {
        if (visited[i] == 0)
        {
            DFSVisit(G, i, visited, order, &pos);
        }
    }

// 全部填满
    return G->nv;
}

// 打印一个序列
void PrintOrder(const char *tag, int order[], int n)
{
// 循环用
    int i;

    printf("%s", tag);
    for (i = 0; i < n; i++)
    {
        printf("%d ", order[i]);
    }
    printf("\n");
}


// 检查一个序列是不是合法拓扑序
int CheckOrder(DGraph *G, int order[])
{
// 每个顶点在序列里的位置
    int pos[MAXV];
// 循环用
    int i, j;

// 先记下位置
    for (i = 0; i < G->nv; i++)
    {
        pos[order[i]] = i;
    }

// 检查每条边
    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
// 有边 i→j，那 i 必须排在 j 前面
            if (G->g[i][j] != 0 && pos[i] >= pos[j])
            {
                printf("  违反：边 %d→%d，但 %d 排在 %d 后面\n", i, j, i, j);
                return 0;
            }
        }
    }
    return 1;
}

// 主函数
int main(void)
{
// 课表：{ 先修课, 后续课 }
    static const int edges[][2] = { { 0, 2 }, { 0, 1 }, { 1, 3 }, { 2, 4 }, { 3, 4 } };
// 顶点数、边数
    int nv = 5;
// 图
    DGraph G;
// 两个算法的结果
    int order1[MAXV];
    int order2[MAXV];
// 排序结果的长度
    int n1, n2;
// 入度数组
    int indegree[MAXV];
// 循环用
    int i, j;

// 建图
    CreateDGraph(&G, nv, edges, 5);

// 打印邻接矩阵
    printf("有向图的邻接矩阵（g[i][j]=1 表示 i→j）：\n");
    printf("      ");
    for (j = 0; j < nv; j++)
    {
        printf("%3d", j);
    }
    printf("\n");

    for (i = 0; i < nv; i++)
    {
        printf("  %2d [", i);
        for (j = 0; j < nv; j++)
        {
            printf("%3d", G.g[i][j]);
        }
        printf(" ]\n");
    }
    printf("（注意矩阵不对称 —— 有向图只填一个格子）\n\n");

// 打印入度出度
    CalcIndegree(&G, indegree);
    printf("各顶点的入度和出度：\n");
    for (i = 0; i < nv; i++)
    {
        printf("  顶点 %d：入度 = %d，出度 = %d\n", i, indegree[i], OutDegree(&G, i));
    }
    printf("（入度 = 我要等谁，出度 = 谁要等我）\n\n");

// Kahn 算法
    n1 = TopSort(&G, order1);
    printf("=== Kahn 算法（入度 + 队列）===\n");
    PrintOrder("  结果: ", order1, n1);
    printf("  排出了 %d / %d 个顶点\n", n1, nv);
    if (n1 == nv)
    {
        printf("  检查合法性: %s\n", CheckOrder(&G, order1) ? "每条边都是从前往后，合法" : "不合法");
    }

// DFS 逆后序
    n2 = TopSortDFS(&G, order2);
    printf("\n=== DFS 逆后序 ===\n");
    PrintOrder("  结果: ", order2, n2);
    printf("  检查合法性: %s\n", CheckOrder(&G, order2) ? "每条边都是从前往后，合法" : "不合法");

// 说明
    printf("\n两个序列不一样，但都合法 —— 拓扑排序不唯一\n");
    printf("（队列里有多个入度 0 的点时，先输出谁都可以）\n\n");

// 有环的情况
    {
// 一个三角形：0→1→2→0
        static const int cyc[][2] = { { 0, 1 }, { 1, 2 }, { 2, 0 } };
