def CreateDGraph(G, nv, edges, edgeCount):
    G.nv = nv
    G.ne = edgeCount

    for i in range(nv):
        for j in range(nv):
            G.g[i][j] = 0

    for i in range(edgeCount):
        G.g[edges[i][0]][edges[i][1]] = 1

def CalcIndegree(G, indegree):
    for i in range(G.nv):
        indegree[i] = 0

    for i in range(G.nv):
        for j in range(G.nv):
            if G.g[i][j] != 0:
                indegree[j] += 1

def OutDegree(G, v):
    count = 0

    for i in range(G.nv):
        if G.g[v][i] != 0:
            count += 1
    return count

def TopSort(G, order):
    indegree = [0] * MAXV
    queue = [0] * MAXV
    front = 0
    rear = 0
    count = 0

    CalcIndegree(G, indegree)

    for i in range(G.nv):
        if indegree[i] == 0:
            queue[rear] = i
            rear += 1

    while front < rear:
        v = queue[front]
        front += 1

        order[count] = v
        count += 1

        for i in range(G.nv):
            if G.g[v][i] != 0:
                indegree[i] -= 1
                if indegree[i] == 0:
                    queue[rear] = i
                    rear += 1

    return count

def HasCycle(G):
    order = [0] * MAXV
    n = TopSort(G, order)

    return n != G.nv

def DFSVisit(G, v, visited, order, pos):
    visited[v] = 1

    for i in range(G.nv):
        if G.g[v][i] != 0 and visited[i] == 0:
            DFSVisit(G, i, visited, order, pos)

    order[pos[0]] = v
    pos[0] -= 1

def TopSortDFS(G, order):
    visited = [0] * MAXV

    for i in range(G.nv):
        visited[i] = 0

    pos = [G.nv - 1]

    for i in range(G.nv):
        if visited[i] == 0:
            DFSVisit(G, i, visited, order, pos)

    return G.nv

